import sys, os, re, json
from html.parser import HTMLParser
src, out = sys.argv[1], sys.argv[2]
pages = sys.argv[3].split()
os.makedirs(out, exist_ok=True)
def anchor(t):
    t = t.lower().strip()
    t = re.sub(r"[^\w\s-]", "", t)
    return re.sub(r"\s+", "-", t)
class P(HTMLParser):
    def __init__(s):
        super().__init__(); s.lines=[]; s.buf=''; s.depth_list=0; s.in_h=None; s.skip=0
    def flush(s, prefix=''):
        t = re.sub(r'\s+', ' ', s.buf).strip()
        if t: s.lines.append(prefix + t)
        s.buf=''
    def handle_starttag(s, tag, a):
        if tag in ('p','li','h1','h2','h3','h4','h5','td','th','tr','blockquote','dt','dd'): s.flush(s.pre())
        if tag in ('ul','ol'): s.flush(s.pre()); s.depth_list+=1
        if tag in ('h1','h2','h3','h4','h5'): s.in_h=int(tag[1])
        if tag in ('strong','b'): s.buf+='**'
        if tag=='li': s.buf=''; s.li=True
        if tag in ('td','th'): s.buf+=' | '
        if tag=='img':
            pass
    def pre(s):
        return ('  '*(s.depth_list-1)+'- ') if getattr(s,'li',False) and s.depth_list else ''
    def handle_endtag(s, tag):
        if tag in ('strong','b'): s.buf+='**'
        if tag in ('h1','h2','h3','h4','h5'):
            t = re.sub(r'\s+',' ',s.buf).strip(); s.buf=''
            s.lines.append(''); s.lines.append('#'*s.in_h+' '+t+'  {#'+anchor(t)+'}'); s.in_h=None
        elif tag in ('p','li','dt','dd','tr','blockquote'):
            s.flush(s.pre()); s.li=False if tag=='li' else getattr(s,'li',False)
        if tag in ('ul','ol'): s.flush(s.pre()); s.depth_list-=1; s.li = s.depth_list>0 and False
    def handle_data(s, d): s.buf+=d
meta={}
for p in pages:
    f = None
    for v in ('v1','v2'):
        c = os.path.join(src, v, 'OEBPS', p + '.xhtml')
        if os.path.exists(c): f = c
    x = P(); x.feed(open(f, encoding='utf-8').read()); x.flush()
    txt = '\n'.join(x.lines)
    hdr = f'PAGE: {p}\nURL: https://learn.microsoft.com/en-us/windows/win32/uxguide/{p}\nSOURCE: Windows 7 UX guide, offline epub copy of MicrosoftDocs/win32 (CC-BY-4.0), supplied by the owner on 2026-10-23\n'
    open(os.path.join(out, p + '.txt'), 'w').write(hdr + txt + '\n')
    meta[p] = {'words': len(txt.split()), 'file': f}
json.dump(meta, open(os.path.join(out, '_meta.json'), 'w'), indent=1)
print(sum(v['words'] for v in meta.values()))
EOF
